        vals=[1.0,.9667,.0]; labels=['Broader v1\nall-detected recall','Broader v1\nstrong-only recall','OPSSAT\nrobust_max recall']; fig,ax=plt.subplots(figsize=(7,4)); ax.bar(labels,vals,color=['#4472c4','#70ad47','#c55a11']); ax.set_ylim(0,1.05); ax.set_ylabel('Recall / detection rate'); ax.set_title('Protocol-specific recall; not directly comparable'); fig.tight_layout(); fig.savefig(OUT/'figures/recall_comparison.png',dpi=180); plt.close(fig)
